@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800;900&display=swap');
:root{color-scheme:dark;--ink:#f6f7fb;--muted:#a9b5c8;--cyan:#5ee7e4;--pink:#ff699e;--gold:#ffdf75}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101a2d;color:var(--ink);font-family:Outfit,system-ui,sans-serif}body{display:grid;place-items:center}.game-shell{position:relative;width:min(100vw,calc(100vh * 1.7778));height:min(100vh,calc(100vw * .5625));min-height:320px;overflow:hidden;background:#172b47;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.game-shell:after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,15,29,.28),transparent 25%,transparent 68%,rgba(9,17,29,.33));z-index:0}.topbar{position:absolute;z-index:2;top:24px;left:34px;right:34px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:white;text-decoration:none;letter-spacing:.08em;font-size:15px;font-weight:900;line-height:.85}.brand b{display:block}.brand small{display:block;color:#9eb0c8;font-size:8px;letter-spacing:.28em;margin-top:6px}.brand-mark{width:30px;height:30px;display:flex;align-items:center;gap:3px;transform:skew(-16deg)}.brand-mark i{display:block;width:6px;border-radius:4px;background:var(--cyan);box-shadow:0 0 12px #5ee7e477}.brand-mark i:nth-child(1){height:14px}.brand-mark i:nth-child(2){height:23px;background:#a0f4e3}.brand-mark i:nth-child(3){height:18px;background:var(--pink)}.hud{display:flex;gap:10px;align-items:center}.hud-stat{position:relative;min-width:94px;height:47px;padding:7px 12px 6px 30px;border:1px solid #ffffff20;background:#111c30a8;backdrop-filter:blur(8px);border-radius:8px;display:flex;flex-direction:column;justify-content:center}.hud-stat .stat-label{font:9px 'DM Mono',monospace;letter-spacing:.16em;color:#9babc1}.hud-stat strong{font:600 16px 'DM Mono',monospace;line-height:1.15;letter-spacing:.03em}.stat-icon{position:absolute;left:11px;top:13px;font-size:15px}.score-icon{color:var(--cyan)}.coin-icon{color:var(--gold);font-size:13px}.best-stat{min-width:82px;padding-left:13px}.sound-button,.pause-button{border:1px solid #ffffff28;background:#111c30ad;color:white;width:38px;height:38px;border-radius:50%;font-size:17px;cursor:pointer;backdrop-filter:blur(8px)}.sound-button:hover,.pause-button:hover{border-color:var(--cyan);color:var(--cyan)}.level-tag{position:absolute;z-index:1;top:95px;left:35px;font:10px 'DM Mono',monospace;letter-spacing:.15em;color:#d4deeb;background:#14203988;border:1px solid #ffffff20;padding:8px 11px;border-radius:4px}.level-tag b{color:var(--cyan);font-weight:500;letter-spacing:.05em}.level-divider{color:#65758a;margin:0 6px}.live-dot,.eyebrow span{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--pink);box-shadow:0 0 10px var(--pink);margin-right:7px;vertical-align:1px}.lane-hint{position:absolute;z-index:1;right:35px;top:98px;color:#d0d8e6;font:9px 'DM Mono',monospace;letter-spacing:.15em;opacity:.76}.lane-hint span{color:var(--cyan);font-size:16px;vertical-align:-2px;margin:0 6px}.overlay{position:absolute;z-index:3;left:9%;top:50%;transform:translateY(-46%);max-width:390px}.intro-overlay{transition:opacity .28s,transform .28s}.intro-overlay.dismiss{opacity:0;transform:translateY(-42%) translateX(-8px);pointer-events:none}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:.18em;color:#d6e0ed;margin-bottom:16px}.overlay h1,.overlay h2{margin:0;font-size:clamp(44px,6.6vw,82px);font-weight:900;line-height:.87;letter-spacing:-.055em}.overlay h1 em,.overlay h2 em{font-style:normal;color:var(--cyan);text-shadow:0 0 32px #5ee7e444}.overlay>p{font-size:15px;line-height:1.5;color:#c3d0df;margin:22px 0 24px}.primary-button{position:relative;border:0;border-radius:5px;padding:15px 20px;min-width:175px;background:var(--cyan);color:#10202e;font:800 12px 'DM Mono',monospace;letter-spacing:.08em;cursor:pointer;box-shadow:0 7px 28px #5ee7e42e;transition:transform .15s,filter .15s}.primary-button span{font-size:17px;margin-left:20px;vertical-align:-1px}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.09)}.primary-button:active{transform:translateY(1px)}.key-guide{display:flex;gap:16px;margin-top:26px;color:#aab8ca;font:9px 'DM Mono',monospace;letter-spacing:.1em;align-items:center}.key-guide span{display:flex;gap:4px;align-items:center}.key-guide kbd,.restart-hint kbd{font:10px 'DM Mono',monospace;display:inline-grid;place-items:center;min-width:19px;height:20px;padding:0 4px;color:#eaf1f8;background:#ffffff13;border:1px solid #ffffff24;border-radius:3px}.pause-overlay,.over-overlay{left:50%;top:50%;transform:translate(-50%,-50%);width:min(440px,86%);text-align:center;padding:32px 28px;border-radius:12px;border:1px solid #ffffff22;background:linear-gradient(135deg,#10203deb,#142a42ed);box-shadow:0 24px 80px #06101ccc;backdrop-filter:blur(14px)}.hidden{display:none!important}.pause-orbit{margin:0 auto 18px;width:50px;height:50px;border-radius:50%;border:1px solid #5ee7e470;color:var(--cyan);display:grid;place-items:center;font-size:23px}.pause-overlay h2,.over-overlay h2{font-size:31px;letter-spacing:-.03em}.pause-overlay>p{margin:12px 0 20px}.text-button{display:block;margin:15px auto 0;background:none;color:#b1c2d5;border:0;font:10px 'DM Mono',monospace;letter-spacing:.15em;cursor:pointer}.text-button:hover{color:white}.over-overlay .eyebrow{margin-bottom:13px}.over-overlay h2{font-size:38px;line-height:.95}.result-row{display:flex;justify-content:center;gap:23px;margin:23px 0}.result-row div{display:flex;flex-direction:column;gap:4px}.result-row small{font:8px 'DM Mono',monospace;color:#91a5bc;letter-spacing:.13em}.result-row strong{font:600 20px 'DM Mono',monospace;color:var(--gold)}.over-overlay .primary-button{margin-top:0}.restart-hint{font:9px 'DM Mono',monospace!important;letter-spacing:.1em;margin:19px 0 0!important;color:#9aabc0!important}.pause-button{position:absolute;z-index:2;right:34px;top:90px;font-size:13px}.toast{position:absolute;z-index:4;top:23%;left:50%;transform:translate(-50%,-10px);opacity:0;padding:9px 14px;border:1px solid #5ee7e455;border-radius:5px;background:#101d31dd;color:var(--cyan);font:10px 'DM Mono',monospace;letter-spacing:.13em;transition:opacity .2s,transform .2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom-note{position:absolute;z-index:1;bottom:20px;left:35px;color:#b5c3d3;font:8px 'DM Mono',monospace;letter-spacing:.15em}.note-separator{color:var(--pink);margin:0 7px}.mobile-controls{display:none}
@media(max-width:700px){.game-shell{width:100vw;height:100dvh;min-height:0}.topbar{top:max(15px,env(safe-area-inset-top));left:16px;right:16px}.brand{font-size:12px}.brand-mark{transform:scale(.85) skew(-16deg);transform-origin:left center;width:26px}.hud{gap:5px}.hud-stat{min-width:67px;height:42px;padding:5px 7px 5px 23px}.hud-stat strong{font-size:12px}.hud-stat .stat-label{font-size:7px}.stat-icon{left:8px;top:12px;font-size:12px}.coin-icon{font-size:11px}.best-stat{display:none}.sound-button{width:33px;height:33px}.level-tag{top:74px;left:16px;font-size:8px;padding:7px}.lane-hint{top:78px;right:17px;font-size:7px}.overlay{left:8%;top:47%;max-width:80%}.overlay h1{font-size:clamp(52px,14vw,76px)}.overlay>p{font-size:13px;margin:17px 0 19px}.key-guide{gap:9px;flex-wrap:wrap;margin-top:18px;font-size:8px}.key-guide kbd{min-width:17px;height:18px}.pause-button{right:17px;top:72px;width:32px;height:32px}.bottom-note{bottom:calc(120px + env(safe-area-inset-bottom));left:16px;font-size:7px}.mobile-controls{position:absolute;z-index:2;left:0;right:0;bottom:max(15px,env(safe-area-inset-bottom));display:flex;justify-content:space-between;align-items:flex-end;padding:0 18px;pointer-events:none}.mobile-controls>button,.mobile-controls div button{pointer-events:auto;width:54px;height:54px;border-radius:50%;border:1px solid #ffffff50;background:#101d31a8;color:#eaf5fa;font-size:31px;line-height:1;backdrop-filter:blur(6px);touch-action:none}.mobile-controls div{display:flex;gap:10px}.mobile-controls div button{width:45px;height:45px;font-size:21px}.mobile-controls button:active{background:#5ee7e455;border-color:var(--cyan)}.pause-overlay,.over-overlay{padding:27px 19px}.over-overlay h2{font-size:32px}.result-row{gap:15px}.result-row strong{font-size:17px}}
@media(max-height:500px) and (min-width:701px){.overlay{top:53%}.overlay h1{font-size:56px}.overlay>p{margin:12px 0 14px}.key-guide{margin-top:14px}.topbar{top:13px}.level-tag,.lane-hint{top:72px}.bottom-note{bottom:12px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {
    score: $('score'), coins: $('coins'), best: $('best'), distance: $('distance'),
    intro: $('introOverlay'), pause: $('pauseOverlay'), over: $('overOverlay'),
    start: $('startButton'), resume: $('resumeButton'), retry: $('retryButton'),
    pauseBtn: $('pauseButton'), finalScore: $('finalScore'), finalCoins: $('finalCoins'),
    finalDistance: $('finalDistance'), toast: $('toast'), sound: $('soundButton')
  };
  const W = 960, H = 540, F = 700, CAM = 8, HORIZON = 0.28 * H;
  const laneX = (lane) => (lane - 1.5) * 1.6;
  let dpr = 1, scaleX = 1, scaleY = 1;
  let state = 'intro', lane = 2, jump = 0, slide = 0, runTime = 0, distance = 0, coins = 0, score = 0;
  let speed = 19, elapsed = 0, spawnTimer = 0, objects = [], particles = [], best = Number(localStorage.getItem('neon-run-best') || 0);
  let lastFrame = 0, toastTimer = 0, audioCtx = null, soundOn = true, shake = 0;
  let pointerStart = null;
  ui.best.textContent = String(best).padStart(6, '0');

  function resize() {
    const rect = canvas.getBoundingClientRect();
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(rect.width * dpr);
    canvas.height = Math.round(rect.height * dpr);
    scaleX = canvas.width / W; scaleY = canvas.height / H;
    ctx.setTransform(scaleX, 0, 0, scaleY, 0, 0);
  }
  window.addEventListener('resize', resize); resize();

  const project = (x, y, z) => {
    const k = F / (CAM + z);
    return { x: W / 2 + x * k, y: HORIZON + (3.1 - y) * k, k };
  };
  const poly = (pts, fill, stroke, lineWidth = 1) => {
    ctx.beginPath(); ctx.moveTo(pts[0].x, pts[0].y);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.lineWidth = lineWidth; ctx.strokeStyle = stroke; ctx.stroke(); }
  };
  const line = (a, b, color, width = 1) => { ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke(); };
  const roundedRect = (x,y,w,h,r,fill) => { ctx.beginPath(); ctx.roundRect(x,y,w,h,r); ctx.fillStyle=fill; ctx.fill(); };

  function drawBackground() {
    const sky = ctx.createLinearGradient(0, 0, 0, H);
    sky.addColorStop(0, '#14243e'); sky.addColorStop(.42, '#526b83'); sky.addColorStop(.66, '#e78f81'); sky.addColorStop(1, '#f4b77e');
    ctx.fillStyle = sky; ctx.fillRect(0,0,W,H);
    const sun = ctx.createRadialGradient(660,155,8,660,155,112);
    sun.addColorStop(0,'#ffe9b8cc'); sun.addColorStop(.22,'#ffb98a88'); sun.addColorStop(1,'#ffb98a00');
    ctx.fillStyle=sun;ctx.fillRect(520,25,280,260);
    ctx.fillStyle='#ffe1b3';ctx.beginPath();ctx.arc(660,155,22,0,Math.PI*2);ctx.fill();
    // distant hills and layered skyline
    poly([{x:0,y:232},{x:120,y:187},{x:220,y:227},{x:330,y:172},{x:470,y:232},{x:620,y:184},{x:780,y:223},{x:960,y:168},{x:960,y:315},{x:0,y:315}], '#435b6c');
    drawCityLayer(0, '#2f465c', 13, 135, 85, 0);
    drawCityLayer(1, '#233a52', 17, 162, 100, 19);
    drawCityLayer(2, '#1a304a', 22, 185, 122, 7);
    // low colored haze
    const haze=ctx.createLinearGradient(0,235,0,340);haze.addColorStop(0,'#ffd3a322');haze.addColorStop(1,'#ffd3a300');ctx.fillStyle=haze;ctx.fillRect(0,230,W,110);
    // lateral embankments
    poly([{x:0,y:270},{x:W/2-166,y:275},{x:W/2-280,y:390},{x:0,y:540}], '#263f43');
    poly([{x:W,y:270},{x:W/2+166,y:275},{x:W/2+280,y:390},{x:W,y:540}], '#263f43');
  }
  function drawCityLayer(layer, color, count, base, maxH, offset) {
    const width=W/count;
    for(let i=0;i<count;i++){
      const x=i*width - (offset + ((distance*0.015) % width));
      const w=width*(.58+((i*17+layer*11)%37)/100);
      const h=32+((i*31+layer*19)%maxH);
      const y=base-h;
      ctx.fillStyle=color;ctx.fillRect(x,y,w,h);
      // roof details and lit windows
      ctx.fillStyle=layer===2?'#31465b':'#536579';
      if(i%3===0)ctx.fillRect(x+w*.58,y-9,w*.12,9);
      for(let wy=y+10;wy<base-4;wy+=12){
        for(let wx=x+7;wx<x+w-5;wx+=12){
          if(((Math.floor(wx)+Math.floor(wy)+i*5)%7)<2){ctx.fillStyle=layer===2?'#f7bf79':'#d7a982';ctx.globalAlpha=.6;ctx.fillRect(wx,wy,3,4);ctx.globalAlpha=1;ctx.fillStyle=layer===2?'#31465b':'#536579';}
        }
      }
    }
  }

  function drawTrack() {
    // Sleeper shadows / tunnel-side ground strips
    for(let z=116;z>0;z-=5){
      const z2=Math.max(0,z-2.5), a=project(-3.2,0,z), b=project(3.2,0,z), c=project(3.2,0,z2), d=project(-3.2,0,z2);
      const band=(Math.floor((z+distance*.8)/5)%2)===0;
      poly([a,b,c,d], band?'#354657':'#2d4051');
    }
    // Rails and road bed trapezoid segments
    const roadColors=['#283847','#293a4a'];
    for(let z=116;z>0;z-=4){
      const z2=Math.max(0,z-4), col=roadColors[Math.floor((z+distance*.6)/4)%2];
      poly([project(-3.2,0,z),project(3.2,0,z),project(3.2,0,z2),project(-3.2,0,z2)],col);
    }
    // outer edge paint
    for(const x of [-3.2,3.2]){
      const a=project(x,0,112),b=project(x,0,0);line(a,b,'#d7a57b77',3);
    }
    // lane dashes and subtle lane guides
    for(const x of [-1.6,0,1.6]){
      const a=project(x,0,112), b=project(x,0,0);line(a,b,'#b7d1d033',1.2);
      for(let z=((distance*1.0)%13);z<112;z+=13){
        const p=project(x,0,z), q=project(x,0,Math.max(0,z-5));
        line(p,q,'#d8e6e744',Math.max(1,p.k*.025));
      }
    }
    // twin rails, sleepers and warm edge lights
    for(const x of [-2.95,-2.72,2.72,2.95]){
      const a=project(x,0,112), b=project(x,0,0);line(a,b,Math.abs(x)>2.8?'#d7c3a9':'#89939b',Math.abs(x)>2.8?2:3);
    }
    for(let z=((distance*1.1)%6);z<112;z+=6){
      const left=project(-3.12,0,z),right=project(3.12,0,z);
      line(left,right,'#a9b5b633',Math.max(.7,left.k*.025));
    }
    // nearby signal lamps
    for(const side of [-1,1]){
      const p=project(side*4.05,0,34);
      ctx.fillStyle='#253749';ctx.fillRect(p.x-3,p.y-96*p.k/87.5,6,96*p.k/87.5);
      ctx.fillStyle='#ff6c91';ctx.shadowColor='#ff6c91';ctx.shadowBlur=14;
      ctx.beginPath();ctx.arc(p.x,p.y-72*p.k/87.5,3.5*p.k/87.5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    }
  }

  function drawCoin(obj) {
    const p=project(laneX(obj.lane), .95+Math.sin(runTime*5+obj.phase)*.07, obj.z);
    const r=Math.max(2, .28*p.k), spin=.32+Math.abs(Math.sin(runTime*7+obj.phase))*.68;
    ctx.save();ctx.translate(p.x,p.y);ctx.scale(spin,1);
    ctx.shadowColor='#ffdf75';ctx.shadowBlur=14*p.k/87.5;
    ctx.fillStyle='#ffdc70';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    ctx.strokeStyle='#fff3bd';ctx.lineWidth=Math.max(1,r*.14);ctx.beginPath();ctx.arc(0,0,r*.72,0,Math.PI*2);ctx.stroke();
    ctx.fillStyle='#b17735';ctx.font=`bold ${Math.max(7,r*1.15)}px Outfit`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✦',0,1);
    ctx.restore();
  }

  function drawBox(laneId,z,width,height,baseColor,topColor,frontColor) {
    const x=laneX(laneId), half=width/2;
    const p1=project(x-half,0,z),p2=project(x+half,0,z),p3=project(x+half,height,z),p4=project(x-half,height,z);
    const dx=F/(CAM+z)*.12, dy=F/(CAM+z)*.13;
    poly([p4,p3,{x:p3.x+dx,y:p3.y-dy},{x:p4.x+dx,y:p4.y-dy}],topColor);
    poly([p2,{x:p2.x+dx,y:p2.y-dy},{x:p3.x+dx,y:p3.y-dy},p3],baseColor);
    poly([p1,p2,p3,p4],frontColor, '#fff0d02c', Math.max(.5,p1.k*.012));
    return {x:p1.x,y:p4.y,w:p2.x-p1.x,h:p1.y-p4.y};
  }
  function drawObstacle(obj) {
    if(obj.type==='barrier'){
      const b=drawBox(obj.lane,obj.z,1.22,.72,'#b84f4d','#ffbd6d','#ee805d');
      const bandH=Math.max(3,b.h*.18);ctx.save();ctx.beginPath();ctx.rect(b.x,b.y+b.h-bandH,b.w,bandH);ctx.clip();
      ctx.strokeStyle='#ffe5af';ctx.lineWidth=Math.max(2,b.w*.055);
      for(let i=-b.h;i<b.w+b.h;i+=b.w*.24){ctx.beginPath();ctx.moveTo(b.x+i,b.y+b.h);ctx.lineTo(b.x+i+b.h*.55,b.y+b.h-bandH);ctx.stroke();}ctx.restore();
      // glowing cap
      ctx.fillStyle='#ffd38a';ctx.fillRect(b.x,b.y+b.h*.18,b.w,Math.max(2,b.h*.035));
    } else if(obj.type==='beam'){
      const x=laneX(obj.lane), z=obj.z;
      const l=project(x-.66,1.17,z),r=project(x+.66,1.17,z),lt=project(x-.66,1.43,z),rt=project(x+.66,1.43,z);
      poly([lt,rt,r,l],'#d15d70','#ffd2a655',1);
      for(const side of [-1,1]){
        const a=project(x+side*.57,0,z),b=project(x+side*.57,1.45,z);
        line(a,b,'#8e5661',Math.max(3,a.k*.055));
        const c=project(x+side*.57,1.47,z);ctx.fillStyle='#ff9f91';ctx.beginPath();ctx.arc(c.x,c.y,Math.max(2,c.k*.035),0,Math.PI*2);ctx.fill();
      }
      const p=project(x,1.3,z);ctx.fillStyle='#fff0d4';ctx.font=`bold ${Math.max(6,p.k*.09)}px DM Mono`;ctx.textAlign='center';ctx.fillText('SLIDE',p.x,p.y-2);
    }else{
      const b=drawBox(obj.lane,obj.z,1.5,1.42,'#50717d','#9bd4c8','#477b83');
      // stylized express train face
      const sx=b.w*.14, sy=b.h*.17;
      roundedRect(b.x+sx,b.y+sy,b.w*.72,b.h*.32,Math.max(2,b.w*.035),'#20384b');
      ctx.fillStyle='#bdf7ed';ctx.globalAlpha=.8;
      ctx.fillRect(b.x+sx*1.35,b.y+sy*1.25,b.w*.23,b.h*.19);ctx.fillRect(b.x+b.w*.56,b.y+sy*1.25,b.w*.23,b.h*.19);ctx.globalAlpha=1;
      ctx.fillStyle='#f0b576';ctx.fillRect(b.x,b.y+b.h*.77,b.w,b.h*.08);
      ctx.fillStyle='#ffda78';ctx.shadowColor='#ffcf73';ctx.shadowBlur=8;
      ctx.beginPath();ctx.arc(b.x+b.w*.2,b.y+b.h*.87,Math.max(2,b.w*.045),0,Math.PI*2);ctx.arc(b.x+b.w*.8,b.y+b.h*.87,Math.max(2,b.w*.045),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
    }
  }

  function drawObjects(){
    const sorted=objects.slice().sort((a,b)=>b.z-a.z);
    for(const o of sorted){if(o.z<118&&o.z>-4){if(o.type==='coin')drawCoin(o);else drawObstacle(o);}}
  }

  function drawCharacter(){
    const x=laneX(lane), base=project(x,0,0), lift=jump>0?Math.sin((1-jump/.88)*Math.PI)*.86:0;
    const slideFactor=slide>0?Math.max(0,1-slide/.72):0;
    const bob=jump>0?0:Math.abs(Math.sin(runTime*13))*.055;
    const s=base.k/87.5, cx=base.x, ground=base.y;
    // shadow
    ctx.save();ctx.globalAlpha=.34*(1-lift*.45);ctx.fillStyle='#091624';ctx.beginPath();ctx.ellipse(cx,ground+3,22*s*(1-lift*.18),7*s,0,0,Math.PI*2);ctx.fill();ctx.restore();
    ctx.save();ctx.translate(cx,ground-lift*75*s);
    if(slideFactor>.05){
