    if((key==='enter'||key===' ')&&state==='over')startRun();
    if((key==='enter'||key===' ')&&state==='intro')startRun();
  });
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='running')togglePause();});
  requestAnimationFrame(loop);
